  pressure:{pa:1,kpa:1000,bar:1e5,psi:6894.757293168,atm:101325}
};
function toC(v,u){ if(u==='C')return v; if(u==='F')return (v-32)/1.8; if(u==='K')return v-273.15; return null; }
function fromC(c,u){ if(u==='C')return c; if(u==='F')return c*1.8+32; if(u==='K')return c+273.15; return null; }
function convertTemp(v,from,to){
  var c=toC(v,from); if(c===null) return {error:'unknown unit'};
  var out=fromC(c,to); if(out===null) return {error:'unknown unit'};
  return {value:out, error:null};
}
function convert(value, from, to, category){
  if(category==='temperature') return convertTemp(value, from, to);
  var table=UNIT_FACTORS[category];
  if(!table) return {error:'unknown category'};
  if(table[from]===undefined || table[to]===undefined) return {error:'unknown unit'};
  var base=value*table[from];
  return {value: base/table[to], error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { convert:convert, UNIT_FACTORS:UNIT_FACTORS };
}
if (typeof window !== 'undefined') {
  window.UnitForgePure = { convert:convert, UNIT_FACTORS:UNIT_FACTORS };
}
